\begin{frame}{}
\vfill
\begin{center}
\begin{minipage}{0.75\textwidth}
\Large
``The most important part of any secret is the knowledge that a secret exists.''
\end{minipage}
\end{center}

\source{yudkowsky2015}

\note{
\begin{itemize}
\item Harry, explaining to Hermione why he cannot teach her his version of the Patronus Charm
\item Even if she kept the method secret, showing the result would reveal that there is something to find
\item This is the difference between steganography and encryption: encryption hides what a message says, steganography hides that there is a message
\end{itemize}
}
\end{frame}

\begin{frame}{What is Steganography?}
\begin{columns}[T]
\begin{column}{0.47\textwidth}
\textbf{Cryptography}
\begin{itemize}
\item Hides the \textbf{content} of a message
\item Outsiders cannot read it
\item But everyone sees that a secret is being sent
\end{itemize}
\end{column}
\begin{column}{0.47\textwidth}
\textbf{Steganography}
\begin{itemize}
\item Hides the \textbf{existence} of a message
\item The secret sits inside an innocent-looking cover
\item An observer sees only ordinary communication
\end{itemize}
\end{column}
\end{columns}
\vspace{1.5em}
\begin{center}
Covers can be images, text, sound files or even network protocols.
\end{center}

\note{
\begin{itemize}
\item Steganography is the art and science of hidden communication
\item Cryptography protects the content of a message by making it unreadable to outsiders
\item Steganography conceals the very existence of the message
\item The secret is embedded in an innocent-looking cover: an image, a line of text, a sound file, a network protocol
\item Core question: how can information be transmitted without revealing that communication is taking place at all?
\item Link back to the Stego Game from this morning
\end{itemize}
}
\end{frame}

\begin{frame}{The Setup}
\begin{center}
\begin{tikzpicture}[
  box/.style={rectangle, draw, thick, rounded corners=3pt, minimum width=1.9cm, minimum height=0.75cm, font=\small},
  arr/.style={->, very thick, gray!70},
]
  \node[font=\small] (m) at (0, 0) {message $m$};
  \node[box, fill=blue!15] (enc) at (2.6, 0) {Encoder $E$};
  \node[box, fill=green!15, minimum width=2.4cm, align=center] (x) at (5.8, 0) {stegotext $x$ \\ {\scriptsize on channel $C$}};
  \node[box, fill=blue!15] (dec) at (9.0, 0) {Decoder $D$};
  \node[font=\small] (m2) at (11.6, 0) {message $m$};
  \node[box, fill=orange!15] (key) at (5.8, -1.4) {secret key $k$};
  \node[box, fill=red!15] (w) at (5.8, 1.4) {Warden};

  \draw[arr] (m) -- (enc);
  \draw[arr] (enc) -- (x);
  \draw[arr] (x) -- (dec);
  \draw[arr] (dec) -- (m2);
  \draw[arr] (key) -| (enc);
  \draw[arr] (key) -| (dec);
  \draw[arr, dashed] (x) -- (w);
  \node[font=\scriptsize, right] at (7.0, 1.4) {innocent or stego?};
\end{tikzpicture}
\end{center}
\vspace{-0.5em}
\begin{columns}[T]
\begin{column}{0.47\textwidth}
\small
\begin{itemize}
\item Encoder $E$ and decoder $D$ share a secret key $k$
\item A channel $C$ carries the messages
\item A distribution $\mathcal{D}$ of innocent messages
\item A message space $M$ of possible secrets
\end{itemize}
\end{column}
\begin{column}{0.47\textwidth}
\small
\begin{itemize}
\item A warden observes the channel
\item \textbf{Correctness}: decoding succeeds with high probability
\item \textbf{Security}: the warden's distinguishing advantage is small
\end{itemize}
\end{column}
\end{columns}

\note{
\begin{itemize}
\item Sender and receiver are often called encoder and decoder, they share a secret key
\item The channel is where messages are transmitted
\item The innocent distribution describes what ordinary communication over the channel looks like
\item The message space contains the secret messages the sender may wish to transmit
\item The encoding procedure embeds a secret message into an apparently innocent message
\item The decoding procedure recovers it
\item The adversary, or warden, observes the communication and tries to distinguish ordinary messages from steganographic ones
\item Two conditions: correctness and security
\item Ask: who played which role in the Stego Game?
\end{itemize}
}
\end{frame}

\begin{frame}{Detection as Hypothesis Testing}
\begin{columns}[c]
\begin{column}{0.5\textwidth}
\begin{description}
\item[Innocent channel] the normal language model
\item[Covertext] the model's response
\item[Hidden message] a payload embedded in the response
\item[Adversary] sees the response and decides: ordinary or stego?
\end{description}
\end{column}
\begin{column}{0.45\textwidth}
For a prompt $p$:
\begin{align*}
P &= \mathrm{Model}(p) && \text{innocent} \\
Q &= \mathrm{Steg}_k(p, m) && \text{stego}
\end{align*}
The adversary tests
\begin{align*}
H_0 &: x \sim P \\
H_1 &: x \sim Q
\end{align*}
\end{column}
\end{columns}

\note{
\begin{itemize}
\item Now the same setup in the LLM setting
\item The innocent channel is the normal language model, the covertext is the model's response
\item The hidden message is a payload embedded in that response
\item $P$ is the innocent distribution over responses for a prompt $p$
\item $Q$ is the steganographic distribution when hiding message $m$ with key $k$
\item The adversary performs hypothesis testing between the two
\item The goal is that the adversary cannot reliably distinguish these two cases
\end{itemize}
}
\end{frame}

\begin{frame}{Perfect Security}
The strongest notion is \textbf{perfect information-theoretic indistinguishability}:
$$P = Q \quad \Longleftrightarrow \quad d_{\mathrm{TV}}(P, Q) = 0$$
with the total variation distance
$$d_{\mathrm{TV}}(P, Q) = \frac{1}{2} \sum_x |P(x) - Q(x)|$$
\vspace{0.5em}
\begin{itemize}
\item One sample, equal priors: the best possible adversary succeeds with probability
$$\Pr[\text{correct}] = \frac{1}{2}\left(1 + d_{\mathrm{TV}}(P, Q)\right)$$
\item If $d_{\mathrm{TV}} = 0$, no adversary can do better than guessing, even with unlimited computation
\end{itemize}

\note{
\begin{itemize}
\item Perfect security means the stego output distribution is exactly the same as the innocent output distribution
\item Total variation distance is the operational distance for hypothesis testing
\item If the adversary gets one sample and both hypotheses have equal prior probability, the optimal success probability is $\frac{1}{2}(1 + d_{\mathrm{TV}})$
\item So with $d_{\mathrm{TV}} = 0$ no adversary, even an unbounded one, can distinguish stego output from innocent output
\item Question for the room: can we have this? What does it cost?
\end{itemize}
}
\end{frame}

\begin{frame}{Perfect Security Needs Long Keys}
\begin{columns}[c]
\begin{column}{0.54\textwidth}
$M$: message, $X$: stegotext, $K$: key
\begin{itemize}
\item Perfect security: $I(M; X) = 0$
\item Perfect decoding: $H(M \mid X, K) = 0$
\end{itemize}
\vspace{0.5em}
\small
\begin{align*}
H(M) &= H(M \mid X, K) + I(M; X, K) \\
     &= \underbrace{H(M \mid X, K)}_{=0} + \underbrace{I(M; X)}_{=0} + I(M; K \mid X) \\
     &\leq H(K \mid X) \leq H(K)
\end{align*}
\end{column}
\begin{column}{0.44\textwidth}
\begin{center}
\begin{tikzpicture}
  \fill[gray!25] (0, 0) rectangle (1.7, 0.7);
  \fill[orange!35] (1.7, 0) rectangle (4.1, 0.7);
  \fill[gray!25] (4.1, 0) rectangle (5.8, 0.7);
  \draw[thick] (0, 0) rectangle (5.8, 0.7);
  \draw[thick] (1.7, 0) -- (1.7, 0.7);
  \draw[thick] (4.1, 0) -- (4.1, 0.7);
  \draw[decorate, decoration={brace, amplitude=5pt}, thick] (0, 0.85) -- (5.8, 0.85)
    node[midway, above=6pt] {$H(M)$};
  \node[below, font=\scriptsize, align=center] at (0.85, 0) {$I(M; X)$ \\ $= 0$};
  \node[below, font=\scriptsize, align=center] at (2.9, 0) {$I(M; K \mid X)$ \\ $\leq H(K)$};
  \node[below, font=\scriptsize, align=center] at (4.95, 0) {$H(M \mid X, K)$ \\ $= 0$};
\end{tikzpicture}
\end{center}
\vspace{1em}
\begin{center}
\fbox{$H(M) \leq H(K)$}
\end{center}
\end{column}
\end{columns}

\note{
\begin{itemize}
\item Perfect hiddenness: the observed stegotext reveals no information about the hidden message
\item Perfect decoding: the receiver recovers $M$ exactly from the stegotext and the key
\item First line is the definition of mutual information, second line is the chain rule
\item Mutual information is bounded by entropy: $I(M; K \mid X) \leq H(K \mid X) \leq H(K)$
\item The picture: the entropy of the message splits into three parts, two of them are forced to zero
\item Result: the shared secret must contain at least as much entropy as the hidden message
\end{itemize}
}
\end{frame}

\begin{frame}{Why This Is Impractical}
\begin{itemize}
\item The key has to grow linearly with the message
\item Arbitrarily many hidden messages need an unbounded supply of shared randomness, or a way to refresh it
\item This is the one-time pad again: perfect secrecy consumes key material
\item Whoever can exchange that much secret randomness could often use that channel directly
\end{itemize}
\vspace{1em}
Steganography is still not useless: it hides the \textbf{existence} of communication, encryption only hides the \textbf{content}.

\vspace{1em}
Practical schemes use a short reusable key and settle for \textbf{computational security}.

\note{
\begin{itemize}
\item $H(M) \leq H(K)$ means the key length scales linearly with the message length
\item A finite fixed key is not enough for arbitrarily many hidden messages
\item Analogous to the one-time pad
\item If sender and receiver already have a secret channel for large amounts of fresh randomness, they could often use it directly for communication or key refreshment
\item That does not make steganography useless, since it hides the existence of communication
\item But perfect information-theoretic steganography is usually expensive in secret randomness
\item So practical schemes use a short reusable key
\end{itemize}
}
\end{frame}

\begin{frame}{Computational Security}
Weaken the requirement:
\vspace{0.5em}
\begin{columns}[T]
\begin{column}{0.47\textwidth}
\textbf{Perfect}
\begin{itemize}
\item $P = Q$
\item \emph{No one} can distinguish the two distributions
\end{itemize}
\end{column}
\begin{column}{0.47\textwidth}
\textbf{Computational}
\begin{itemize}
\item $P \approx Q$ for efficient observers
\item No \emph{polynomial-time} adversary can distinguish them with non-negligible advantage
\end{itemize}
\end{column}
\end{columns}
\vspace{1.5em}
\begin{center}
An unbounded adversary may still break the scheme.
\end{center}

\note{
\begin{itemize}
\item Instead of demanding $P = Q$ against all adversaries, we demand that no efficient adversary can distinguish $P$ from $Q$
\item The guarantee is not: no one can distinguish the two distributions
\item It is: no polynomial-time adversary can distinguish them with non-negligible advantage
\item This is a reasonable assumption about real adversaries
\item An unbounded adversary may still break the scheme
\end{itemize}
}
\end{frame}

\begin{frame}{Pseudorandom Functions}
A \textbf{PRF} is a family of keyed functions
$$F_k : \{0,1\}^{\ell_1} \to \{0,1\}^{\ell_2}, \qquad \text{one for each key } k \in \{0,1\}^{\lambda}$$
\begin{enumerate}
\item $F_k$ is efficiently computable given $k$
\item For every polynomial-time distinguisher $D$ and a truly random function $f$:
$$\tfrac{1}{2} \Pr_{k \sim \mathrm{Unif}(\{0,1\}^\lambda)}\big[\, D^{F_k} = 0 \,\big] + \tfrac{1}{2} \Pr_{f}\big[\, D^{f} = 1 \,\big] \leq \tfrac{1}{2} + \mathrm{negl}(\lambda)$$
$$\text{where } \forall c > 0 \;\, \exists N \;\, \forall \lambda > N : \;\; \mathrm{negl}(\lambda) < \lambda^{-c}$$
\end{enumerate}
\vspace{0.5em}
A short key, but to efficient algorithms it looks like a truly random function.

\note{
\begin{itemize}
\item $\lambda$ is the key length, input and output lengths are polynomial in $\lambda$
\item The distinguisher gets oracle access: it can query the function but does not see the key
\item $f$ is a truly random function with the same domain and range
\item Intuition: a truly random function requires an enormous amount of randomness
\item A PRF uses only a short key
\item But to efficient algorithms it looks like a truly random function
\end{itemize}
}
\end{frame}

\begin{frame}{Assumptions and Attack Cost}
\begin{columns}[T]
\begin{column}{0.47\textwidth}
\textbf{Assumption}
\begin{itemize}
\item One-way functions exist
\item This implies that PRFs exist
\item $P \neq NP$ alone is too weak for modern cryptography
\end{itemize}
\vspace{0.5em}
\textbf{Security argument}
\begin{enumerate}
\item Assume secure PRFs exist
\item Replace true randomness by PRF output
\item Efficient adversaries cannot tell the difference
\item So they cannot tell stego from innocent output
\end{enumerate}
\end{column}
\begin{column}{0.47\textwidth}
\textbf{Attack cost}
\begin{itemize}
\item Generic attack: try all keys of length $\lambda$
$$O(2^\lambda)$$
\item For each key, check whether the text has the expected statistical structure
\item A weak PRF or a flawed construction allows faster attacks
\item A good scheme makes exhaustive search the best strategy
\end{itemize}
\end{column}
\end{columns}

\note{
\begin{itemize}
\item The relevant assumption is not simply $P \neq NP$, that is too weak for modern cryptography
\item The standard assumption is the existence of one-way functions, which implies the existence of PRFs
\item Go through the four steps of the security argument
\item Efficient adversaries cannot distinguish stego output from innocent output, except with negligible advantage
\item Brute force: for each candidate key the attacker checks whether the observed text has the statistical structure expected under that key
\item If the correct key is found, the attacker can run the retrieval algorithm and decode the payload
\item The attack cost is at most $2^\lambda$ by exhaustive search
\item An unbounded adversary can still brute-force the key
\end{itemize}
}
\end{frame}

\begin{frame}{Summary: The Trade-off}
\begin{center}
\renewcommand{\arraystretch}{1.4}
\begin{tabular}{lll}
\toprule
 & \textbf{Perfect} & \textbf{Computational} \\
\midrule
Guarantee & $P_{\text{stego}} = P_{\text{innocent}}$ & no efficient distinguisher \\
Key & $H(K) \geq H(M)$, fresh & short, reusable \\
Assumption & none & secure PRFs exist \\
Unbounded adversary & still secure & breaks it, cost up to $2^\lambda$ \\
\bottomrule
\end{tabular}
\end{center}

\note{
\begin{itemize}
\item Perfect information-theoretic steganography requires the stego distribution to equal the innocent distribution exactly
\item With perfect decoding it requires $H(K) \geq H(M)$
\item So unlimited perfect hidden communication requires an unlimited or refreshed secret resource
\item Computational steganography uses a short reusable key and a PRF
\item The output is computationally indistinguishable from innocent model output, assuming the PRF is secure
\item Practical, but only against efficient adversaries
\end{itemize}
}
\end{frame}

\begin{frame}{Perfect Security with LLMs: Coupling}
Recap: perfect security needs $H(K) \geq H(M)$, so first encrypt with a one-time pad.
The ciphertext $X = M \oplus K$ is uniform, the receiver recovers $X$ and XORs with $K$.
\vspace{0.5em}
\begin{columns}[T]
\begin{column}{0.4\textwidth}
\textbf{Given} (both fixed)
\begin{itemize}
\item Ciphertext $X$, uniform
\item Covertext $C$, the LLM's distribution
\end{itemize}
\end{column}
\begin{column}{0.55\textwidth}
\textbf{Find} a randomized encoder $f: x \mapsto S$ with
\begin{itemize}
\item $S \sim C$ exactly (perfect security)
\item $I(X; S)$ as large as possible
\end{itemize}
\end{column}
\end{columns}
\vspace{0.5em}
\begin{itemize}
\item \textbf{Theorem 1}: $f$ is perfectly secure iff it samples $S$ from row $x$ of a \textbf{coupling}, a joint table over $(X, C)$ with row sums $X$ and column sums $C$
\item \textbf{Theorem 2}: the coupling with maximal $I(X; S)$ is the one with \textbf{minimum joint entropy} $H(X, S)$ (MEC)
\end{itemize}

\source{dewitt2022}

\note{
\begin{itemize}
\item This is the perfectly secure counterpart to the PRF scheme that follows
\item It uses Cachin's model: everyone, including the adversary, knows the covertext distribution exactly
\item Step 1 is the one-time pad from the theory part, the key is as long as the message
\item Theorem 1 is almost a tautology: the stegotext marginal equals the covertext distribution exactly when the joint is a coupling
\item Theorem 2: $I(X; S) = H(X) + H(S) - H(X, S)$, $H(X)$ is fixed and $H(S) = H(C)$ by perfect security, so maximising information means minimising the joint entropy
\item So the question ``what is the best perfectly secure scheme'' becomes ``find the minimum entropy coupling''
\end{itemize}
}
\end{frame}

\begin{frame}{Minimum Entropy Coupling: Example}
\begin{center}
\includegraphics[height=0.48\textheight]{figures/mec_coupling.pdf}
\end{center}
\vspace{-0.5em}
\begin{itemize}
\item Left: independent coupling, the token says nothing about $X$
\item Right: MEC, $1.30$ of the $1.49$ bits of token entropy carry ciphertext
\item Sender: given $x$, sample the token from row $x$
\item Receiver: given the token, read off the posterior over $x$ (\texttt{fox}: $x = 11$ for sure, \texttt{dog}: $01$ with probability $5/6$)
\end{itemize}

\source{dewitt2022}

\note{
\begin{itemize}
\item Both tables have the same row sums ($0.25$ each) and the same column sums ($0.5$, $0.3$, $0.2$), so both are perfectly secure
\item The independent coupling ignores the ciphertext completely, it is secure but useless
\item The MEC concentrates mass on few cells, so the token is informative about $x$
\item Computed with the greedy algorithm of Kocaoglu et al.\ 2017: repeatedly match the largest remaining row mass with the largest remaining column mass
\item Exact MEC is NP-hard, but greedy approximations are within about one bit of optimal and keep the marginals exact
\item The toy example is my own, not from the paper
\end{itemize}
}
\end{frame}

\begin{frame}{iMEC: Coupling Token by Token}
Ciphertext and text are far too large for one coupling table, so couple step by step.
\begin{columns}[T]
\begin{column}{0.42\textwidth}
\begin{itemize}
\item Keep a posterior $\mu$ over the ciphertext (start: uniform)
\item Each token $j$: couple $\mu$ with the LLM's next-token distribution, sample $S_j$, update $\mu$ to the posterior given $S_j$
\item The receiver runs the same computation and ends with the MAP ciphertext
\item Stop once $H(\mu) < 0.1$ bits
\end{itemize}
\end{column}
\begin{column}{0.56\textwidth}
\includegraphics[width=\textwidth]{figures/imec_posterior.pdf}
\end{column}
\end{columns}

\source{dewitt2022}

\note{
\begin{itemize}
\item iMEC is from Sokota et al.\ 2022, de Witt et al.\ apply it to steganography
\item The ciphertext is split into blocks, each step couples the block with the highest remaining entropy
\item Every step is a coupling, so every token has exactly the LLM's distribution, perfect security holds for the whole text
\item The plot is my own toy simulation: each line is one run, the receiver's uncertainty falls roughly by the entropy of each token
\item The receiver needs the exact same next-token distributions as the sender: the same model, the same prompt, deterministic numerics
\end{itemize}
}
\end{frame}

\begin{frame}{Task}
\centering
\Large Come up with a steganography protocol that does not assume the decoder has access to the probabilities.
\end{frame}

\begin{frame}{PRF + LLM = Undetectable Steganography}
\begin{center}
\begin{tikzpicture}[
  x=0.75cm,
  y=1cm,
  font=\small,
  tokenbrace/.style={decorate, decoration={brace, mirror, amplitude=5pt}},
]
  \draw[thick] (0, 0) -- (10, 0);
  \foreach \x in {0, 5, 8, 10}
    \draw[thick] (\x, -0.18) -- (\x, 0.18);

  \draw[tokenbrace] (0, -0.25) -- (5, -0.25) node[midway, below=7pt] {\texttt{cat}: $0.5$};
  \draw[tokenbrace] (5, -0.25) -- (8, -0.25) node[midway, below=7pt] {\texttt{dog}: $0.3$};
  \draw[tokenbrace] (8, -0.25) -- (10, -0.25) node[midway, below=7pt] {\texttt{fox}: $0.2$};

  \node[anchor=east] at (-0.3, 0) {$\mathrm{LLM}(\text{prompt}) =$};
  \node[anchor=east] (prf) at (3.2, 0.9) {$F_k(\text{symbol}) = 0.62$};
  \draw[thick, ->, red!70!black] (prf.east) -- (6.2, 0.9) -- (6.2, 0.08);
  \fill[red!70!black] (6.2, 0) circle (2pt);
  \node[anchor=west] at (10.4, 0) {$\Longrightarrow$ \texttt{dog}};
\end{tikzpicture}
\end{center}
\vspace{-0.3em}
\begin{itemize}
\item Normal sampling: draw a uniform $u \in [0, 1]$ and pick the token whose interval contains $u$
\item Steganography: replace $u$ by the output of a secret-keyed PRF that depends on the hidden symbol
\item The PRF output looks uniform, so the token distribution is unchanged
\item Any signal with entropy can be turned into a stego channel this way
\end{itemize}

\source{zamir2024}

\note{
\begin{itemize}
\item At every step the language model produces a probability distribution over the next token
\item Example: cat $0.5$, dog $0.3$, fox $0.2$
\item Normally the model samples a random number $u$ and chooses the token by cumulative probability intervals: cat if $u < 0.5$, dog if $0.5 \leq u < 0.8$, fox if $0.8 \leq u < 1$
\item The paper keeps this exact sampling procedure, but generates $u$ with a secret-keyed PRF instead of fresh randomness
\item The model still outputs cat, dog and fox with probabilities $0.5$, $0.3$, $0.2$
\item The hidden message is encoded by making the PRF input depend on the hidden symbol currently being transmitted
\item Sender and receiver share the PRF and the secret key $k$
\end{itemize}
}
\end{frame}

\begin{frame}{Sending and Decoding a Symbol}
\begin{columns}[T]
\begin{column}{0.47\textwidth}
\textbf{Sender}
\begin{itemize}
\item Wants to transmit a symbol $\sigma \in \{\texttt{0}, \texttt{1}, \leftarrow\}$
\item Samples with randomness
$$F_k(r, i, \sigma)$$
\item $k$: secret key, $i$: token position, $r$: prefix of this response
\item Pushes the same symbol for several consecutive tokens
\end{itemize}
\end{column}
\begin{column}{0.47\textwidth}
\textbf{Receiver}
\begin{itemize}
\item Knows $k$, sees the tokens
\item Keeps a score for every candidate symbol $\texttt{0}, \texttt{1}, \leftarrow$
\item The score of the correct symbol tends to grow faster
\item Once a score crosses a threshold $t$: record the symbol, reset the scores
\end{itemize}
\end{column}
\end{columns}

\source{zamir2024}

\note{
\begin{itemize}
\item To transmit a code symbol the generator uses randomness $F_k(r, i, \sigma)$
\item $k$ is the secret key, $i$ is the token position, $r$ is a response-specific random prefix
\item For several consecutive tokens the generator samples using the PRF stream of the current symbol
\item The visible text still follows the normal LLM distribution
\item The decoder knows $k$, so for the observed tokens it computes scores for each candidate symbol
\item The correct symbol's score tends to grow faster
\item Once one score crosses a threshold, the decoder records that symbol and resets the scores
\item Then the sender moves on to the next symbol
\end{itemize}
}
\end{frame}

\begin{frame}{Encoding: Sampling a Token Bit by Bit}
\begin{columns}[T]
\begin{column}{0.45\textwidth}
\begin{center}
\begin{tikzpicture}[
  font=\small,
  inner/.style={draw, rounded corners, inner sep=3pt},
  leaf/.style={inner sep=2pt},
  edge/.style={thick, ->},
  chosen/.style={very thick, ->, red!70!black},
]
  \node[inner] (root) at (0, 0) {start};
  \node[inner] (l) at (-1.5, -1.4) {\texttt{cat}/\texttt{dog}};
  \node[inner] (r) at (1.5, -1.4) {\texttt{fox}/\texttt{owl}};
  \node[leaf, align=center] (cat) at (-2.4, -3) {\texttt{cat}\\$00$\\$0.4$};
  \node[leaf, align=center, text=red!70!black] (dog) at (-0.6, -3) {\texttt{dog}\\$01$\\$0.3$};
  \node[leaf, align=center] (fox) at (0.6, -3) {\texttt{fox}\\$10$\\$0.2$};
  \node[leaf, align=center] (owl) at (2.4, -3) {\texttt{owl}\\$11$\\$0.1$};
  \draw[chosen] (root) -- node[left, pos=0.4] {$0$} (l);
  \draw[edge] (root) -- node[right, pos=0.4] {$1$} (r);
  \draw[edge] (l.south) -- node[left] {$0$} (cat.north);
  \draw[chosen] (l.south) -- node[right] {$1$} (dog.north);
  \draw[edge] (r.south) -- node[left] {$0$} (fox.north);
  \draw[edge] (r.south) -- node[right] {$1$} (owl.north);
\end{tikzpicture}
\end{center}
\end{column}
\begin{column}{0.52\textwidth}
Rule: bit $i$ is $1$ iff $u_i \leq p_i$, with $u_i = F_k(r, i, \sigma)$
\begin{enumerate}
\item Bit 1: $p_1 = P(\texttt{fox}/\texttt{owl}) = 0.3$ \\
$u_1 = 0.62 > 0.3 \Rightarrow$ bit $0$
\item Bit 2: $p_2 = P(\texttt{dog} \mid \texttt{cat}/\texttt{dog}) = \frac{0.3}{0.7} \approx 0.43$ \\
$u_2 = 0.25 \leq 0.43 \Rightarrow$ bit $1$
\item Bits $01 \Rightarrow$ output \texttt{dog}
\end{enumerate}
\end{column}
\end{columns}

\source{zamir2024}

\note{
\begin{itemize}
\item Write every token ID in binary, here 4 tokens need 2 bits
\item Choosing the token is the same as choosing its bits one after another
\item At each node, $p_i$ is the probability that the next bit is $1$, computed from the LLM's token probabilities
\item The sender uses $u_i = F_k(r, i, \sigma)$ as the random number, where $\sigma$ is the symbol currently being sent
\item Because $u_i$ looks uniform, \texttt{dog} still comes out with probability $0.7 \cdot \frac{3}{7} = 0.3$
\item Real vocabularies have about $32{,}000$ tokens, so about $15$ bits per token
\item The numbers are my own toy example
\end{itemize}
}
\end{frame}

\begin{frame}{Decoding: Scoring the Candidates}
The receiver sees \texttt{dog}, so the bits are $x_1 = 0$, $x_2 = 1$.
For each candidate symbol it recomputes $u_i$ and scores how well the bits fit:
$$s(x_i, u_i) = \begin{cases} \ln \frac{1}{u_i} & x_i = 1 \\ \ln \frac{1}{1 - u_i} & x_i = 0 \end{cases}$$
\begin{center}
\renewcommand{\arraystretch}{1.3}
\begin{tabular}{lcccc}
\toprule
Candidate & $u_1$ & $s(0, u_1)$ & $u_2$ & $s(1, u_2)$ \\
\midrule
Correct $\sigma$ & $0.62$ & $\ln \frac{1}{0.38} = 0.97$ & $0.25$ & $\ln \frac{1}{0.25} = 1.39$ \\
Wrong $\sigma'$ & $0.45$ & $\ln \frac{1}{0.55} = 0.60$ & $0.70$ & $\ln \frac{1}{0.70} = 0.36$ \\
\bottomrule
\end{tabular}
\end{center}
\begin{itemize}
\item Correct $\sigma$: total $2.36$, wrong $\sigma'$: total $0.96$
\item The receiver never uses $p_1$ or $p_2$
\end{itemize}

\source{zamir2024}

\note{
\begin{itemize}
\item The receiver turns the observed token back into bits with the tokenizer
\item For each candidate symbol it computes $u_i = F_k(r, i, \sigma')$ and adds up the scores
\item A $1$ only comes out when $u_i \leq p_i$, so with the correct symbol, $1$s come with small $u_i$ and $0$s with large $u_i$, both give high scores
\item With a wrong symbol, $u_i$ is unrelated to the bits, the score is on average $1$ per bit
\item The correct score grows faster, roughly by the entropy of the text
\item Low-entropy bits ($p_i$ close to $0$ or $1$) give the correct symbol almost no advantage
\item The receiver needs only the key and the tokenizer, not the model
\end{itemize}
}
\end{frame}

\begin{frame}{Perfect vs Computational Steganography with LLMs}
\begin{center}
\renewcommand{\arraystretch}{1.3}
\begin{tabular}{lll}
 & \textbf{iMEC} (de Witt et al.) & \textbf{PRF scheme} (Zamir) \\
\hline
Security & perfect, $\mathrm{KL} = 0$ & computational, assumes PRFs \\
Key & one-time pad, as long as message & short, reusable \\
Receiver needs & model + prompt, exact numerics & key + text only \\
Capacity & close to the entropy & $\Theta(L)$ bits, larger constants \\
Many queries & fresh key material each time & random-prefix trick \\
\end{tabular}
\end{center}

\source{dewitt2022,zamir2024}

\note{
\begin{itemize}
\item Both schemes leave the token distribution unchanged, they differ in what the receiver must know and how strong the guarantee is
\item iMEC: the receiver has to recompute every next-token distribution, so it must know the model and the prompt and reproduce the sampling bit for bit
\item Zamir: the decoder only needs the key and the text, Zamir points this out as the defining difference of the LLM setting: the channel distribution is unknown to the receiver
\item Safety angle: a model leaking information to an outside reader who does not see the prompt fits Zamir
\item Two instances of the same model that share the context, e.g.\ a policy and an untrusted monitor, could in principle use MEC
\end{itemize}
}
\end{frame}

\begin{frame}{From Steganography to Watermarking}
A watermark is steganography with a \textbf{one-bit payload}: ``this text came from our model''.
\vspace{0.5em}
\begin{itemize}
\item Same construction: the sampler's randomness comes from a keyed pseudorandom function of the key and the preceding tokens
\item Different goal: robust detection, and the adversary wants to \emph{remove} the mark
\end{itemize}
\vspace{0.5em}
\begin{description}
\item[2022] Scott Aaronson and Hendrik Kirchner propose the Gumbel scheme at OpenAI
\item[2024] SynthID-Text by Google DeepMind, based on tournament sampling
\item[2026] Claude's text watermark, a version of the SynthID-Text approach, announced in August for the EU AI Act transparency rules
\end{description}

\source{aaronson2023,dathathri2024}

\note{
\begin{itemize}
\item The steganography paper extends earlier work by Christ, Gunn and Zamir on undetectable watermarks
\item A watermark only says: this came from the model, there is no message to decode
\item Anthropic describes Claude's watermark as a version of the SynthID-Text approach, in a family of approaches that goes back to Aaronson's 2022 proposal
\item The method is public, the key and the exact parameters are not
\item Nothing is added to the text, there are no hidden characters
\item Detection works badly on short texts and on passages with few free choices, such as code
\item Light editing does not remove it, a complete rewrite does
\end{itemize}
}
\end{frame}

\begin{frame}{The Gumbel Watermark}
\begin{columns}[T]
\begin{column}{0.47\textwidth}
\textbf{Generation}
\begin{itemize}
\item Model gives probabilities $p_v$
\item One pseudorandom number per token $v$:
$$r = F_k(\text{previous tokens}) \in [0, 1]^{|V|}$$
\item Output
$$x = \arg\max_v \; r_v^{1/p_v}$$
\item Token $v$ wins with probability exactly $p_v$
\end{itemize}
\end{column}
\begin{column}{0.47\textwidth}
\textbf{Detection}
\begin{itemize}
\item Needs the key and the text, not the model
\item Recompute $r$ for every observed token $x_i$
$$S = \sum_{i=1}^{n} -\ln\left(1 - r_{x_i}\right)$$
\item No watermark: $S \sim \mathrm{Gamma}(n, 1)$, mean $n$
\item Watermark: $S$ is larger, the gap grows with the entropy of the text
\end{itemize}
\end{column}
\end{columns}

\source{aaronson2023}

\note{
\begin{itemize}
\item This is the scheme you will implement in the exercise
\item The key and the previous few tokens seed the pseudorandom numbers
\item The argmax rule is the Gumbel-max trick: over random $r$ token $v$ wins with probability exactly $p_v$, so the output distribution is unchanged
\item But the chosen token tends to have $r_v$ close to $1$
\item Detection: without a watermark the $r$ values of the observed tokens are uniform, so each term is exponential with mean $1$
\item The sum of $n$ such terms follows a Gamma distribution with shape $n$, which gives a p-value
\item Low-entropy text leaves the model few choices, so it carries little watermark
\end{itemize}
}
\end{frame}

